function goldGrad(id){return '<linearGradient id="'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="'+C.goldB+'"/><stop offset="1" stop-color="'+C.goldD+'"/></linearGradient>';}
function border(W,H,rad){return '<rect x="1.5" y="1.5" width="'+(W-3)+'" height="'+(H-3)+'" rx="'+rad+'" fill="none" stroke="#F5F1E6" stroke-opacity=".12" stroke-width="3"/>';}
function livePill(x,y){var tw=estW('LIVE',24,4),total=16+12+tw,sx=x+(176-total)/2;
 return '<rect x="'+x+'" y="'+y+'" width="176" height="54" rx="27" fill="'+C.red+'"/><circle cx="'+(sx+8)+'" cy="'+(y+27)+'" r="8" fill="'+C.ivory+'"/>'+T(sx+28,y+35,'LIVE',{s:24,w:800,fill:C.ivory,ls:4});}
// Resta dov'era — si aggancia all'angolo in alto a sinistra e cresce verso
// il basso e verso destra — ma si vede. Era 22px con tre di spaziatura su un
// fondo trasparente al 55%: sulla card della piattaforma diventa due pixel
// sopra la foto, e la spaziatura in piccolo sfalda la parola invece di
// darle aria. Ora il fondo e' quasi pieno, il testo piu' grande e piu'
// stretto.
// La misura non puo' essere un numero fisso: 30px su una card da 924 sono
// una targhetta giusta, sugli stessi 30px di un 1920 diventano un francobollo
// — e' lo stesso disegno mostrato a meta' scala. Si misura sulla larghezza del
// formato, con un fondo: sotto i 30px non scende, cosi' le card piccole
// restano come sono adesso e i formati larghi crescono.
function engPill(x,y,label,wFmt,hFmt){var t=label||'English Commentary';
 // larghezza per crescere, altezza per non sfondare: su un banner mid, alto
 // 412, una misura presa solo dalla larghezza diventerebbe una fascia.
 var s=Math.max(30,Math.min(R((wFmt||1080)*0.022),R((hFmt||1080)*0.075)));
 var pad=R(s*0.93),w=Math.round(estW(t,s,1.5))+pad*2,h=R(s*2.27);
 return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="'+R(h/2)+'" fill="#0A0F24" fill-opacity=".88" stroke="'+C.ivory+'" stroke-opacity=".9" stroke-width="'+Math.max(2,R(s*0.083))+'"/>'+T(x+w/2,y+R(h*0.66),t,{s:s,w:800,fill:C.ivory,ls:1.5,anchor:'middle'});}
