// Avvolto in G('brand') come gli altri oggetti: resta trascinabile e ridimensionabile.
function brandLogo(){return (typeof LOGO_LIB!=='undefined'&&LOGO_LIB.como_tv)?LOGO_LIB.como_tv.d:'';}
