 var M=R(W*0.056),homeS=R(W*0.10*TEAM_SCALE),vsS=R(W*0.036*TEAM_SCALE),kickS=R(W*0.030),dtS=R(W*0.042),preS=R(W*0.026),footS=R(W*0.024);
 var bm=R(H*0.05),footY=H-bm,lineY=footY-R(footS*1.7),badgeR=R(footS*1.05),badgeCy=footY-R(footS*0.33);
 var dtY=lineY-R(W*0.028),awayY=dtY-R(homeS*0.6),homeY=awayY-R(homeS*0.9),kickY=homeY-R(homeS*0.95),tickH=R(kickS*0.9);
 var scrim='<defs><linearGradient id="spP" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="'+SCRIM+'"/><stop offset=".12" stop-color="'+SCRIM+'" stop-opacity=".96"/><stop offset=".5" stop-color="#0A0F24" stop-opacity=".5"/><stop offset=".82" stop-color="#0A0F24" stop-opacity=".05"/><stop offset="1" stop-color="#0A0F24" stop-opacity="0"/></linearGradient>'+goldGrad('gpP')+'</defs>';
 var pv='';if(p.preshow&&p.showPreshow!==false){var px=M+R(W*0.36),pw=R(estW(up(p.preshow),preS,3))+R(preS*1.6),ph2=R(preS*2);pv=G('cta',A,'<rect x="'+px+'" y="'+(dtY-R(preS*1.35))+'" width="'+pw+'" height="'+ph2+'" rx="'+R(preS*0.35)+'" fill="url(#gpP)"/>'+T(px+R(preS*0.8),dtY-R(preS*0.1),p.preshow,{s:preS,w:800,fill:C.n900,ls:3}));}
 return GPHOTO(W,H,A,I)+scrim+'<rect width="'+W+'" height="'+H+'" fill="url(#spP)" pointer-events="none"/>'
  +(!hl&&p.live?G('live',A,livePill(W-M-176,R(H*0.04))):'')
  +(p.english?G('eng',A,engPill(M,R(H*0.04),p.englishLabel,W,H)):'')
